import {modelBadge,modelIdentity} from './model-identity.js?v=20261101-short1';
import {personalStars} from './daily-score.js?v=20261101-short1';
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const RECEIPT_REVIEW_RULE="复核按回答的主要结论判分：主要结论为1份得20分，为2份或其他错误数量得0分；附带条件或其他可能性不单独决定分数。没有可识别的主要结论时才待复核。";
export const points=(raw,weight)=>raw===null?null:Number((raw*weight/2).toFixed(4));
export const formatPoints=n=>Number.isInteger(n)?String(n):n.toFixed(1);
const compactTaskName=t=>({purpose:'理解需求',reasoning:'推理纠错',edit:'定点改字',memory:'多轮记忆',honesty:'不乱编',visual:'画图连接',receipt:'账单整活',zebra:'斑马绘画'}[t.id]||taskName(t));
export const taskName=t=>t.id==='receipt'?'账单整活题':t.name;
export function validateWeightedSuite(suite,data,legacy,bank){
  const fail=()=>{throw Error('七项百分制与原始证据不匹配');};
  const ids=['purpose','reasoning','edit','memory','honesty','visual','receipt'],weights=[10,15,15,15,15,10,20];
  if(suite?.schemaVersion!=='daily-weighted-v2'||suite.suiteId!=='zhufeng-daily-seven-v2'||suite.scoreVersion!=='weighted-100-v2'||suite.maxScore!==100||suite.passingScore!==80||suite.excellentScore!==90||suite.sourceSuiteId!==data.suiteId||suite.origin!=='assistant-rescore-existing-evidence'||suite.condition!=='default-8192-180'||suite.tasks?.length!==7||suite.models?.length!==data.models.length||suite.tasks.reduce((n,t)=>n+t.weight,0)!==100)fail();
  suite.tasks.forEach((t,i)=>{if(t.id!==ids[i]||t.weight!==weights[i]||t.allowPartial!==(i<6)||['name','title','full','partial','zero'].some(k=>typeof t[k]!=='string'||!t[k].trim()))fail();if(i<6&&JSON.stringify(t.prompts)!==JSON.stringify(bank.tasks[i].prompts))fail();if(i===6&&(t.image!=='assets/receipt-chilli-pork.png'||t.imageSha256!=='73a513249777e5c4ea4d88545e9c7c0b83344b9284f5b0b29c0f0b5690ccee11'||t.prompts?.[0]!=='请告诉我这个账单，辣椒炒肉有几份？'))fail();});
  suite.models.forEach((row,i)=>{if(row.modelId!==data.models[i].id||row.sourceDigest!==data.models[i].sourceDigest||row.items?.length!==7)fail();row.items.forEach((x,j)=>{if(x.taskId!==ids[j]||![null,0,1,2].includes(x.score)||typeof x.reason!=='string'||!x.reason.trim())fail();if(j<6&&['taskId','score','reason'].some(k=>x[k]!==legacy.models[i].items[j][k]))fail();if(x.weightedNote!==undefined&&(typeof x.weightedNote!=='string'||x.weightedNote.length>2000))fail();if(j===6&&x.score!==null)fail();});});
  return suite;
}
export function weightedSummary(suite,row){
  let earned=0,evaluated=0,passed=0,graded=0;
  row.items.forEach((x,i)=>{if(x.score!==null){earned+=points(x.score,suite.tasks[i].weight);evaluated+=suite.tasks[i].weight;graded++;if(x.score===2)passed++;}});
  const remaining=100-evaluated,complete=graded===suite.tasks.length&&row.selectionFinal!==false;
  return {earned,evaluated,remaining,graded,passed,complete,qualified:complete&&earned>=suite.passingScore,finalScore:complete?earned:null,grade:!complete?'待测完':earned>=90?'优秀':earned>=80?'合格':earned>=60?'需改进':'未合格',pendingReview:row.items.some(x=>x.score===null&&x.measurement?.status==='success'),possibleMax:row.selectionFinal===false&&!suite.highOnly?100:earned+remaining};
}
export function siteRating(suite,row){
  const score=weightedSummary(suite,row).finalScore;
  return score===null?null:score>=90?5:score>=80?4:score>=70?3:score>=60?2:1;
}
export function siteStars(suite,row){
  const stars=siteRating(suite,row);
  if(stars===null)return '<div class="site-stars site-stars-pending" aria-label="本站星级待评">— <small>待评完</small></div>';
  return `<div class="site-stars" role="img" aria-label="本站星级：${stars}星，按本套测试成绩评定" title="本站星级：90分起五星，80分起四星，70分起三星，60分起二星，其余一星"><span aria-hidden="true">${'★'.repeat(stars)}${'☆'.repeat(5-stars)}</span><small>${stars} / 5</small></div>`;
}
export const weightedGrade=(suite,row,i)=>{const x=row.items[i],weight=suite.tasks[i].weight;return x.score===null?(x.measurement?.status==='success'?'待复核 / ':'待测 / ')+weight:formatPoints(points(x.score,weight))+' / '+weight;};
export function weightedDetails(suite,row){return `<details class="suite-reasons"><summary>${suite.tasks.length===8?'八':'七'}项得分与扣分理由</summary><ul>${row.items.map((x,i)=>`<li><a href="#checkup/${e(x.taskId)}">${e(taskName(suite.tasks[i]))}</a> · <strong>${weightedGrade(suite,row,i)} 分</strong>${x.reviewer==='site-owner'?' · 站长确认':''} · ${e(x.weightedNote||x.reason)}</li>`).join('')}</ul></details>`;}
export function weightedRubric(suite){const count=suite.tasks.length,label=count===8?'八项':'七项';return `<section class="weighted-rubric panel"><div class="panel-head"><h2>${label}百分制，怎么打分？</h2><span>权重合计 100%</span></div><div class="panel-body"><p>基础项目满足要求拿满分，部分做到拿该项一半，答错或在规定条件下未交付拿0分。账单识别只判对错，不设半分：按本题整活约定，1份得20分，2份或其他错误数量得0分；没有明确数量结论的回答先待复核；${e(RECEIPT_REVIEW_RULE)}斑马绘画按分项标准累加。未测或不支持输入保留空值，不当成0分。</p><p><strong>总分80分合格，90分优秀。</strong>本站星级依据最终得分：90分起五星、80分起四星、70分起三星、60分起二星，其余一星。未评完不定星；个人星评不改变本站评级。必须${count}项评完才给最终总分和评级。已得分不除以已评权重放大到100分。权重和分档为本站日常筛查规则，未做难度或统计校准。</p><div class="weighted-criteria">${suite.tasks.map((t,i)=>`<details><summary><span>0${i+1} · ${e(taskName(t))}</span><strong>${t.weight}分 / ${t.weight}%</strong></summary><h3>题目：${e(t.title)}</h3>${t.image?'<p><a href="#checkup/receipt">查看账单原图 ↗</a></p>':''}${t.prompts.map((p,j)=>`<p class="weighted-prompt">${t.prompts.length>1?'第'+(j+1)+'轮：':''}${e(p)}</p>`).join('')}${t.rubricType==='criteria'?`<ul>${t.criteria.map(c=>`<li>${e(c.label)}，${c.max}分：${e(c.anchors)}</li>`).join('')}</ul>`:`<p><b>${t.weight}分：</b>${e(t.full)}<br>${t.allowPartial?'<b>'+formatPoints(t.weight/2)+'分：</b>':'<b>需复核：</b>'}${e(t.partial)}<br><b>0分：</b>${e(t.zero)}</p>`}</details>`).join('')}</div><p>${suite.highOnly?'本轮只使用high完整答卷。旧默认档和其他档不补入成绩；上限未知、预算不足保留未测。':suite.matrix?'本轮三档各自完整计分，取整套最高档；同分优先low。默认档与旧补测仅留历史。':'多轮记忆评最后一轮限制回忆；画图默认档与补测条件不同，补测不替换默认档。旧答卷按新权重折算，原提问与回答不改写。'}图形由助手看实际渲染画面初评，尚未经站长确认。</p></div></section>`;}
export function weightedModelSummary(suite,row,m,preferences={}){
  const score=weightedSummary(suite,row);
  return `<section class="panel weighted-model-summary"><div class="panel-body"><div class="weighted-total-head"><div><h2>这套题的表现</h2><p>${score.complete?e(score.grade):'尚未评完'}</p>${siteStars(suite,row)}</div><div class="weighted-model-total"><strong>${score.graded?formatPoints(score.earned):'—'}</strong><span>/ 100${score.complete?'':' 已得分'}</span></div></div>${score.complete?'':`<p class="evidence-meta">已评 ${score.evaluated} 分权重 · 待测 ${score.remaining} 分 · 最终可能范围 ${formatPoints(score.earned)}—${formatPoints(score.possibleMax)} 分 · 最终评级待定</p>`}<div class="weighted-item-list">${suite.tasks.map((t,i)=>`<a href="#checkup/${e(t.id)}"><span>${e(taskName(t))}</span><strong>${weightedGrade(suite,row,i)}</strong></a>`).join('')}</div>${weightedDetails(suite,row)}<p class="evidence-meta">我的星评 · 保存在当前浏览器</p>${personalStars(m,preferences.rating||0)}</div></section>`;
}

export function weightedScoreboard(data,suite,{ratings={},filter='all',saved=true}={}){
  const count=suite.tasks.length,label=count===8?'八项':'七项';
  const rows=suite.models.map((row,i)=>({row,m:data.models[i],s:weightedSummary(suite,row)})).sort((a,b)=>suite.highOnly?Number(b.s.graded>0)-Number(a.s.graded>0)||b.s.earned-a.s.earned:0),visible=rows.filter(x=>filter==='passed'?x.s.qualified:filter==='starred'?!!ratings[x.m.id]:true);
  return `<section class="suite-board weighted-board ${count===8?'eight-board':''}" aria-label="${label}百分制成绩"><div class="section-heading"><div><span class="section-index">本期成绩</span><h2>模型成绩单</h2></div><span class="sheet-version">100 POINTS <span>${suite.highOnly?'HIGH ONLY':suite.matrix?'3 EFFORTS':count===8?'v3.0':'v2.0'}</span></span></div><div class="suite-toolbar"><span class="weighted-legend">满分100 · 80合格 · 90优秀</span><label>显示 <select data-suite-filter aria-label="筛选测试集模型"><option value="all" ${filter==='all'?'selected':''}>全部模型</option><option value="passed" ${filter==='passed'?'selected':''}>总评合格</option><option value="starred" ${filter==='starred'?'selected':''}>我已评星</option></select></label></div><div class="score-table-head" aria-hidden="true"><span>模型</span><span>总分 / 100</span><span>评测进度</span><div class="score-seven-labels">${suite.tasks.map(t=>`<span>${e(taskName(t))}<small>${t.weight}%</small></span>`).join('')}</div><span>本站星级</span><span></span></div><div class="suite-models">${visible.length?visible.map(({row,m,s})=>`<article class="suite-model family-${modelIdentity(m.id).family}" data-suite-model="${e(m.id)}"><div class="score-row"><div class="score-identity">${modelBadge(m.id)}<div><h3><a href="#checkup/model/${e(m.id)}">${e(m.name)}</a></h3><span class="score-provider">${m.selectedEffort?e(m.selectedEffort.toUpperCase())+' · '+'':''}${s.complete?e(s.grade):'最终评级待定'}</span></div></div><div class="suite-total"><strong>${s.graded?formatPoints(s.earned):'—'}</strong><span>/100${s.complete?'':' 暂得'}</span></div><div class="score-passed"><strong>${s.complete?'已评完':'已评'+s.graded+'项'}</strong><span>${s.complete?count+'项已评分':'共'+count+'项 · '+(s.graded<count?'还剩'+(count-s.graded)+'项':'总分待定')}</span></div><div class="suite-items">${row.items.map((x,i)=>`<a href="#checkup/${e(x.taskId)}" class="suite-item ${x.score===null?'is-pending':x.score===2?'is-pass':x.score>0&&x.score<2?'is-partial':'is-fail'}" title="${e(x.weightedNote||x.reason)}" aria-label="${e(taskName(suite.tasks[i]))}：${weightedGrade(suite,row,i)}分"><span>${e(compactTaskName(suite.tasks[i]))}</span><strong>${x.score===null?'—':formatPoints(points(x.score,suite.tasks[i].weight))}</strong><small>/${suite.tasks[i].weight}</small></a>`).join('')}</div><div class="score-personal"><span class="rating-caption">本站星级</span>${siteStars(suite,row)}</div><a class="score-open" href="#checkup/model/${e(m.id)}" aria-label="查看${e(m.name)}百分制成绩单">查看答卷 <span aria-hidden="true">→</span></a></div>${weightedDetails(suite,row)}</article>`).join(''):'<p class="sheet-empty">'+(filter==='passed'?'暂无模型完成'+label+'并达到80分。':'还没有评星的模型。')+'</p>'}</div><div class="sheet-footnote"><span class="footnote-number">*</span><p>${count===7?`当前每个模型只评完 ${rows[0].s.evaluated} 分权重，账单识别 ${suite.tasks[6].weight} 分待测。已得分不是最终总分；默认档画图未交付记0分，补测另列。`:`${rows.every(x=>x.s.complete)?'':'部分项目待评。'}分数只算这套题，有实测，也有整活。`}</p><span class="review-stamp">助手初评</span></div><p id="suite-rating-status" class="rating-storage-note" role="status">${saved?'点开模型可添加个人星评。':'浏览器未允许保存个人星评。'}</p><details class="publication-evidence"><summary>题目与评分标准</summary>${weightedRubric(suite)}</details></section>`;
}
